import Foundation
var failures = 0
for title in ["PRIVATE_TOOL_ARGUMENT", "PRIVATE_REASONING_SUMMARY", "PRIVATE_OPAQUE_SIGNATURE"] {
    let state = ChatActivityAttributes.ContentState(statusLabel: title)
    let encoded = try JSONEncoder().encode(state)
    if state.statusLabel != "Working…" || String(decoding: encoded, as: UTF8.self).contains(title) {
        print("FAIL: newly created lock-screen state contains trace sentinel")
        failures += 1
    }
}
let sentinel = "PRIVATE_RESTORED_TOOL_TITLE"
let saved = try JSONSerialization.data(withJSONObject: ["statusLabel": sentinel])
let restored = try JSONDecoder().decode(ChatActivityAttributes.ContentState.self, from: saved)
let restoredJSON = try JSONEncoder().encode(restored)
if restored.statusLabel != "Working…" || String(decoding: restoredJSON, as: UTF8.self).contains(sentinel) {
    print("FAIL: restored lock-screen state rediscloses saved trace sentinel")
    failures += 1
}
if failures == 0 { print("PASS: new and restored ActivityKit state withhold trace sentinels") }
exit(failures == 0 ? 0 : 1)
